const D = { energy:.55, density:.5, scale:1, speed:1, wind:.45, alpha:.6, hue:44, x:.5, y:.45, style:'dapple', act:'breeze', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lrp=(a,b,t)=>a+(b-a)*t;
const md=(a,n)=>((a%n)+n)%n;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const W=width, Hh=height, u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style, act=P.act||'breeze';
const isPin=st==='pinhole', isCon=st==='contour', isStip=st==='stipple';
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const en=clp(P.energy,0,1), dn=clp(P.density,0,1), al=clp(P.alpha,0,1);
const sp=P.speed, sc=clp(P.scale,0.25,2.4), wd=Math.abs(P.wind);
const cx=P.x*W, cy=P.y*Hh;
let envW=1, warm=0, elong=1;
if(act==='gust'){ envW=0.55+1.9*K.intensity; }
else if(act==='sundown'){ const s2=clp(0.5+0.5*Math.sin(K.t*0.019-1.2),0,1); warm=-26*s2; elong=1+1.35*s2; envW=0.8; }

// ---- pre-blurred gap sprites: a soft sun pool, and the eclipse crescent ----
if(!S.sp){
  const SZ=64; S.sp=[];
  const g0=createGraphics(SZ,SZ); g0.pixelDensity(1); g0.colorMode(HSB,360,100,100,100); g0.clear(); g0.noStroke();
  for(let r=28;r>0;r-=1.5){ g0.fill(0,0,100,4.2); g0.circle(32,32,r*2); }
  g0.filter(BLUR,4); S.sp.push(g0);
  const g1=createGraphics(SZ,SZ); g1.pixelDensity(1); g1.colorMode(HSB,360,100,100,100); g1.clear(); g1.noStroke();
  g1.fill(0,0,100,100); g1.circle(32,32,50);
  g1.erase(); g1.circle(43,25,44); g1.noErase();   // bite out of the disc = partial-eclipse crescent
  g1.filter(BLUR,2); S.sp.push(g1);
}

// ---- the gaps in the canopy: each pool is a pinhole image of the sun ----
const nP=Math.round(lrp(18,80,dn));
const spread=u*0.85*sc;
const pool=i=>{
  const j=i*11;
  const bx=cx+(fr(j+1)-0.5)*spread*1.5, by=cy+(fr(j+2)-0.5)*spread*1.1;
  // leaves shuffling above the gap: the pool jitters on two incommensurate rates AND breathes open/shut
  const w1=(0.29+fr(j+3)*0.63)*sp, w2=(0.71+fr(j+4)*1.37)*sp;
  const jx=(Math.sin(K.t*w1+fr(j+5)*6.283)*0.7+Math.sin(K.t*w2*1.31+fr(j+6)*6.283)*0.3)*u*0.055*wd*envW*sc;
  const jy=(Math.sin(K.t*w2+fr(j+7)*6.283)*0.6+Math.sin(K.t*w1*1.73+fr(j+8)*6.283)*0.4)*u*0.040*wd*envW*sc;
  const op=0.5+0.5*Math.sin(K.t*(0.17+fr(j+9)*0.41)*sp*envW+fr(j+10)*6.283);
  const shut=clp((op-0.28)/0.72,0,1);                     // a leaf slides over and the pool winks out
  const rad=u*lrp(0.020,0.075,fr(j+11))*sc*(0.45+0.9*en);
  return [bx+jx, by+jy, rad, shut];
};

// ---- canopy shade: big soft masses drifting over everything ----
if(!isCon&&!isStip){
  for(let i=0;i<6;i++){
    const j=i*31+400;
    const bx=cx+(fr(j+1)-0.5)*spread*1.6+Math.sin(K.t*(0.031+fr(j+2)*0.043)*sp)*u*0.08*wd*envW;
    const by=cy+(fr(j+3)-0.5)*spread*1.2+Math.sin(K.t*(0.047+fr(j+4)*0.037)*sp+1.9)*u*0.05*wd*envW;
    const r=u*lrp(0.28,0.62,fr(j+5))*sc;
    tint(md(H+150,360), 26, 22, clp(11*al*(0.4+0.6*en),0,16));
    imageMode(CENTER); image(S.sp[0],bx,by,r*2,r*2*lrp(0.7,1.3,fr(j+6))); imageMode(CORNER);
  }
  noTint();
}

// ---- the light ----
const sunAng=K.t*0.013*sp+fr(99)*6.283;
if(isCon){
  noFill();
  for(let i=0;i<nP;i++){
    const p=pool(i); if(p[3]<0.06) continue;
    for(let b=0;b<4;b++){
      const f=b/3;
      stroke(md(H+f*46+warm,360), lrp(76,40,f), lrp(100,62,f), clp((66-b*13)*al*p[3]*(0.35+0.9*en),0,88));
      strokeWeight(Math.max(0.5,u*0.0013*sc));
      ellipse(p[0],p[1],p[2]*2*lrp(0.35,1.5,f)*elong,p[2]*2*lrp(0.35,1.5,f));
    }
  }
} else if(isStip){
  noStroke();
  for(let i=0;i<nP;i++){
    const p=pool(i); if(p[3]<0.06) continue;
    const nd=Math.round(p[3]*(2+7*en));
    for(let k=0;k<nd;k++){
      const j=i*97+k*7, a2=fr(j+1)*6.283, rr=Math.sqrt(fr(j+2))*p[2];
      fill(md(H+warm,360), lrp(48,10,p[3]), 100, clp(88*al*p[3],0,94));
      circle(p[0]+Math.cos(a2)*rr*elong, p[1]+Math.sin(a2)*rr, u*lrp(0.0016,0.0044,fr(j+3))*sc*(0.5+p[3]));
    }
  }
} else {
  blendMode(ADD); imageMode(CENTER);
  for(let i=0;i<nP;i++){
    const p=pool(i); if(p[3]<0.06) continue;
    const flick=1+0.16*Math.sin(K.t*(1.7+fr(i*11+12)*2.9)*sp+fr(i*11+13)*6.283); // leaf edges trembling, small amplitude
    const aa=clp(30*al*p[3]*(0.35+0.95*en)*flick*(1+A.rms*0.35+K.pulse*0.05),0,34);
    if(aa<0.5) continue;
    push(); translate(p[0],p[1]); rotate(isPin?sunAng:sunAng*0.3+fr(i*11+14)*6.283);
    // penumbra then core — soft-edged because the gap is a pinhole, not a window
    tint(md(H+warm-6,360), lrp(58,30,p[3]), 100, aa*0.5);
    image(S.sp[isPin?1:0], 0,0, p[2]*2*(isPin?1.9:2.9)*elong, p[2]*2*(isPin?1.9:2.9));
    tint(md(H+warm+7,360), lrp(42,6,p[3]), 100, aa);
    image(S.sp[isPin?1:0], 0,0, p[2]*2*(isPin?1.25:1.5)*elong, p[2]*2*(isPin?1.25:1.5));
    pop();
  }
  imageMode(CORNER); noTint(); blendMode(BLEND);
}

